      { transform: `translate(${dx / 2}px, ${dy / 2 - 28}px) scale(${(1 + scale) / 2}) rotate(-2deg)`, offset: .5 },
      { transform: `translate(${dx}px, ${dy}px) scale(${scale})`, backgroundColor: getComputedStyle(target).backgroundColor }
